CREATE TABLE IF NOT EXISTS `#__decaromembership_categories` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(190) NOT NULL,`description` TEXT NULL,`fee` DECIMAL(12,2) NULL,`duration_months` INT UNSIGNED NULL,`required_documents` TEXT NULL,`rules` TEXT NULL,`benefits` TEXT NULL,`language` CHAR(7) NOT NULL DEFAULT '*',`ordering` INT NOT NULL DEFAULT 0,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_category_name` (`name`),KEY `idx_category_state` (`published`),KEY `idx_category_language` (`language`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_locations` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(190) NOT NULL,`code` VARCHAR(100) NULL,`number` VARCHAR(100) NULL,`address` VARCHAR(255) NULL,`city` VARCHAR(190) NULL,`province` VARCHAR(100) NULL,`postal_code` VARCHAR(32) NULL,`country` VARCHAR(100) NULL,`email` VARCHAR(190) NULL,`phone` VARCHAR(100) NULL,`manager` VARCHAR(190) NULL,`parent_id` INT UNSIGNED NULL,`language` CHAR(7) NOT NULL DEFAULT '*',`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_location_code` (`code`),UNIQUE KEY `uq_location_number` (`number`),KEY `idx_location_parent` (`parent_id`),KEY `idx_location_state` (`published`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_members` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`first_name` VARCHAR(190) NOT NULL,`last_name` VARCHAR(190) NOT NULL,`birth_date` DATE NULL,`birth_place` VARCHAR(190) NULL,`tax_code` VARCHAR(64) NULL,`address` VARCHAR(255) NULL,`city` VARCHAR(190) NULL,`province` VARCHAR(100) NULL,`postal_code` VARCHAR(32) NULL,`country` VARCHAR(100) NULL,`email` VARCHAR(190) NULL,`phone` VARCHAR(100) NULL,`alternative_contacts` TEXT NULL,`photo` VARCHAR(500) NULL,`notes` TEXT NULL,`member_number` VARCHAR(100) NULL,`card_number` VARCHAR(100) NULL,`first_registration_date` DATE NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'pending',`location_id` INT UNSIGNED NULL,`category_id` INT UNSIGNED NULL,`user_id` INT UNSIGNED NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_member_tax_code` (`tax_code`),UNIQUE KEY `uq_member_number` (`member_number`),UNIQUE KEY `uq_member_card_number` (`card_number`),KEY `idx_member_name` (`last_name`,`first_name`),KEY `idx_member_category` (`category_id`),KEY `idx_member_location` (`location_id`),KEY `idx_member_user` (`user_id`),KEY `idx_member_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_case_statuses` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(190) NOT NULL,`code` VARCHAR(100) NOT NULL,`ordering` INT NOT NULL DEFAULT 0,`language` CHAR(7) NOT NULL DEFAULT '*',`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_case_status_code` (`code`),KEY `idx_case_status_ordering` (`ordering`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_cases` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`reference` VARCHAR(100) NOT NULL,`member_id` INT UNSIGNED NOT NULL,`type` VARCHAR(50) NOT NULL DEFAULT 'registration',`status_id` INT UNSIGNED NULL,`assigned_to` INT UNSIGNED NULL,`source_component` VARCHAR(100) NULL,`source_entity_id` BIGINT UNSIGNED NULL,`received_at` DATE NULL,`completed_at` DATE NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_case_reference` (`reference`),KEY `idx_case_member` (`member_id`),KEY `idx_case_status` (`status_id`),KEY `idx_case_assigned` (`assigned_to`),KEY `idx_case_source` (`source_component`,`source_entity_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_case_status_history` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`case_id` INT UNSIGNED NOT NULL,`old_status_id` INT UNSIGNED NULL,`new_status_id` INT UNSIGNED NULL,`note` TEXT NULL,`user_id` INT UNSIGNED NOT NULL DEFAULT 0,`created` DATETIME NOT NULL,PRIMARY KEY (`id`),KEY `idx_case_history_case` (`case_id`),KEY `idx_case_history_created` (`created`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_renewals` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NOT NULL,`association_year` VARCHAR(20) NOT NULL,`renewal_date` DATE NULL,`expiry_date` DATE NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'due',`amount` DECIMAL(12,2) NULL,`payment_status` VARCHAR(50) NOT NULL DEFAULT 'unpaid',`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_renewal_member_year` (`member_id`,`association_year`),KEY `idx_renewal_status` (`status`),KEY `idx_renewal_expiry` (`expiry_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_cards` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NOT NULL,`card_number` VARCHAR(100) NOT NULL,`type` VARCHAR(30) NOT NULL DEFAULT 'physical',`status` VARCHAR(50) NOT NULL DEFAULT 'pending',`issued_at` DATE NULL,`activated_at` DATE NULL,`expires_at` DATE NULL,`annual_mark` VARCHAR(100) NULL,`qr_token` VARCHAR(190) NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_card_number` (`card_number`),UNIQUE KEY `uq_card_qr_token` (`qr_token`),KEY `idx_card_member` (`member_id`),KEY `idx_card_status` (`status`),KEY `idx_card_expiry` (`expires_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_dues` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NOT NULL,`category_id` INT UNSIGNED NULL,`association_year` VARCHAR(20) NOT NULL,`amount` DECIMAL(12,2) NOT NULL DEFAULT 0,`paid_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,`status` VARCHAR(50) NOT NULL DEFAULT 'unpaid',`due_date` DATE NULL,`reference` VARCHAR(100) NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_due_member` (`member_id`),KEY `idx_due_category` (`category_id`),KEY `idx_due_year` (`association_year`),KEY `idx_due_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_payments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NOT NULL,`due_id` INT UNSIGNED NULL,`amount` DECIMAL(12,2) NOT NULL,`method` VARCHAR(50) NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'pending',`paid_at` DATE NULL,`reference` VARCHAR(190) NULL,`receipt_number` VARCHAR(100) NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_payment_reference` (`reference`),UNIQUE KEY `uq_receipt_number` (`receipt_number`),KEY `idx_payment_member` (`member_id`),KEY `idx_payment_due` (`due_id`),KEY `idx_payment_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_transfers` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`reference` VARCHAR(100) NOT NULL,`member_id` INT UNSIGNED NOT NULL,`from_location_id` INT UNSIGNED NULL,`to_location_id` INT UNSIGNED NOT NULL,`requested_at` DATE NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'requested',`delegation_status` VARCHAR(100) NULL,`card_position` VARCHAR(100) NULL,`arrears_amount` DECIMAL(12,2) NULL,`source_confirmed` TINYINT NOT NULL DEFAULT 0,`destination_confirmed` TINYINT NOT NULL DEFAULT 0,`completed_at` DATE NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_transfer_reference` (`reference`),KEY `idx_transfer_member` (`member_id`),KEY `idx_transfer_from` (`from_location_id`),KEY `idx_transfer_to` (`to_location_id`),KEY `idx_transfer_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_relations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NOT NULL,`related_member_id` INT UNSIGNED NOT NULL,`relation_type` VARCHAR(50) NOT NULL,`valid_from` DATE NULL,`valid_to` DATE NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_relation_member` (`member_id`),KEY `idx_relation_related` (`related_member_id`),KEY `idx_relation_type` (`relation_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_documents` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`title` VARCHAR(255) NOT NULL,`member_id` INT UNSIGNED NULL,`case_id` INT UNSIGNED NULL,`document_type` VARCHAR(100) NOT NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'to_verify',`issued_at` DATE NULL,`expires_at` DATE NULL,`external_component` VARCHAR(100) NULL,`external_document_id` BIGINT UNSIGNED NULL,`fallback_path` VARCHAR(500) NULL,`notes` TEXT NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_document_member` (`member_id`),KEY `idx_document_case` (`case_id`),KEY `idx_document_expiry` (`expires_at`),KEY `idx_document_external` (`external_component`,`external_document_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_checklist_templates` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(190) NOT NULL,`case_type` VARCHAR(50) NOT NULL,`language` CHAR(7) NOT NULL DEFAULT '*',`ordering` INT NOT NULL DEFAULT 0,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_checklist_case_type` (`case_type`),KEY `idx_checklist_language` (`language`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_checklist_items` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`template_id` INT UNSIGNED NULL,`case_id` INT UNSIGNED NULL,`label` VARCHAR(255) NOT NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'missing',`required` TINYINT NOT NULL DEFAULT 1,`ordering` INT NOT NULL DEFAULT 0,`notes` TEXT NULL,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_checkitem_template` (`template_id`),KEY `idx_checkitem_case` (`case_id`),KEY `idx_checkitem_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_notifications` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NULL,`type` VARCHAR(100) NOT NULL,`channel` VARCHAR(30) NOT NULL DEFAULT 'joomla',`subject` VARCHAR(255) NOT NULL,`body` TEXT NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'pending',`scheduled_at` DATE NULL,`sent_at` DATE NULL,`published` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,`modified` DATETIME NULL,`modified_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_notification_member` (`member_id`),KEY `idx_notification_status` (`status`),KEY `idx_notification_schedule` (`scheduled_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_entity_links` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`member_id` INT UNSIGNED NULL,`local_entity_type` VARCHAR(100) NOT NULL,`local_entity_id` BIGINT UNSIGNED NOT NULL,`component` VARCHAR(100) NOT NULL,`external_entity_type` VARCHAR(100) NOT NULL,`external_entity_id` BIGINT UNSIGNED NOT NULL,`relation_type` VARCHAR(100) NOT NULL,`metadata` LONGTEXT NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_entity_link` (`local_entity_type`,`local_entity_id`,`component`,`external_entity_type`,`external_entity_id`,`relation_type`),KEY `idx_entity_link_member` (`member_id`),KEY `idx_entity_link_external` (`component`,`external_entity_type`,`external_entity_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decaromembership_audit_log` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`entity_type` VARCHAR(100) NOT NULL,`entity_id` BIGINT UNSIGNED NOT NULL,`action` VARCHAR(100) NOT NULL,`user_id` INT UNSIGNED NOT NULL DEFAULT 0,`old_values` LONGTEXT NULL,`new_values` LONGTEXT NULL,`ip_hash` CHAR(64) NULL,`created` DATETIME NOT NULL,PRIMARY KEY (`id`),KEY `idx_audit_entity` (`entity_type`,`entity_id`),KEY `idx_audit_user` (`user_id`),KEY `idx_audit_created` (`created`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
